import{_ as t,o as r,c as o,a5 as a}from"./chunks/framework.DJo0M80U.js";const h=JSON.parse('{"title":"HJ68 成绩排序","description":"较难 通过率：22.99% 时间限制：1秒 空间限制：32M 知识点 排序 描述 给定一些同学的信息（名字，成绩）序列，请你将他们的信息按照成绩从高到低或从低到高的排列,相同成绩 都按先录入排列在前的规则处理。 例示： jack 70 peter 96 Tom 70 smith。","frontmatter":{"title":"HJ68 成绩排序","date":"2026-08-11T00:00:00.000Z","categories":["前端面试与实战"],"tags":["前端面试","算法","求职","教程","OneNote","算法训练"],"description":"较难 通过率：22.99% 时间限制：1秒 空间限制：32M 知识点 排序 描述 给定一些同学的信息（名字，成绩）序列，请你将他们的信息按照成绩从高到低或从低到高的排列,相同成绩 都按先录入排列在前的规则处理。 例示： jack 70 peter 96 Tom 70 smith。","sidebarWeight":92,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/a-吊打面试官/算法题/华为较难题/HJ68 成绩排序.md"},"headers":[],"relativePath":"posts/前端面试与实战/03-算法训练/华为较难题/HJ68 成绩排序.md","filePath":"posts/前端面试与实战/03-算法训练/华为较难题/HJ68 成绩排序.md"}'),s={name:"posts/前端面试与实战/03-算法训练/华为较难题/HJ68 成绩排序.md"};function n(d,e,i,c,p,l){return r(),o("div",null,[...e[0]||(e[0]=[a('<div><h1 id="hj68-成绩排序" tabindex="-1">HJ68 成绩排序 <a class="header-anchor" href="#hj68-成绩排序" aria-label="Permalink to &quot;HJ68 成绩排序&quot;">​</a></h1><blockquote><p>本节目标：理解“HJ68 成绩排序”的核心思路，并能把它用于实际开发或面试表达。 较难 通过率：22.99% 时间限制：1秒 空间限制：32M 知识点==排序== <strong>描述</strong> 给定一些同学的信息（名字，成绩）序列，请你将他们的信息按照成绩从高到低或从低到高的排列,相同成绩 都按先录入排列在前的规则处理。 例示： jack 70 peter 96 Tom 70 smith 67 从高到低 成绩 peter 96 jack 70 Tom 70 smith 67 从低到高 smith 67 jack 70 Tom 70 peter 96 注：0代表从高到低，1代表从低到高 数据范围：人数：1≤�≤200 1≤<em>n</em>≤200 进阶：时间复杂度：�(�����) <em>O</em>(<em>nlogn</em>) ，空间复杂度：�(�) <em>O</em>(<em>n</em>) <strong>输入描述：</strong> 第一行输入要排序的人的个数n，第二行输入一个整数表示排序的方式，之后n行分别输入他们的名字和成绩，以一个空格隔开 <strong>输出描述：</strong> 按照指定方式输出名字和成绩，名字和成绩之间以一个空格隔开 <strong>示例1</strong> 输入： 30fang 90yang 50ning 70 ==复制== 输出： fang 90ning 70yang 50 ==复制== <strong>示例2</strong> 输入： 31fang 90yang 50ning 70 ==复制== ==输出：== ==yang 50========ning 70========fang 90======</p></blockquote><p>为了实现这个排序功能，我们需要根据用户的选择来决定是按成绩从高到低还是从低到高排序。Python 的列表排序方法（<code>sort</code> 方法或 <code>sorted</code> 函数）可以方便地实现这一功能。我们可以利用这些方法的 <code>key</code> 参数来指定排序的依据（在这里是成绩），以及 <code>reverse</code> 参数来控制排序的方向。</p><p>下面是一种可能的实现方式：</p><p>def sort_students(n, sort_order, students):</p><h1 id="对学生信息进行排序" tabindex="-1">对学生信息进行排序 <a class="header-anchor" href="#对学生信息进行排序" aria-label="Permalink to &quot;对学生信息进行排序&quot;">​</a></h1><h1 id="sort-order为0时-按成绩降序排列-为1时-按成绩升序排列" tabindex="-1">sort_order为0时，按成绩降序排列；为1时，按成绩升序排列 <a class="header-anchor" href="#sort-order为0时-按成绩降序排列-为1时-按成绩升序排列" aria-label="Permalink to &quot;sort_order为0时，按成绩降序排列；为1时，按成绩升序排列&quot;">​</a></h1><p>students.sort(key=lambda x: x[1], reverse=(sort_order == 0))</p><h1 id="输出排序后的学生信息" tabindex="-1">输出排序后的学生信息 <a class="header-anchor" href="#输出排序后的学生信息" aria-label="Permalink to &quot;输出排序后的学生信息&quot;">​</a></h1><p>for student in students: print(student[0], student[1])</p><h1 id="读取输入" tabindex="-1">读取输入 <a class="header-anchor" href="#读取输入" aria-label="Permalink to &quot;读取输入&quot;">​</a></h1><p>n = int(input()) # 学生人数 sort_order = int(input()) # 排序方式：0为降序，1为升序 students = [] for _ in range(n): name, score = input().split() students.append((name, int(score)))</p><h1 id="调用函数进行排序并输出结果" tabindex="-1">调用函数进行排序并输出结果 <a class="header-anchor" href="#调用函数进行排序并输出结果" aria-label="Permalink to &quot;调用函数进行排序并输出结果&quot;">​</a></h1><p>sort_students(n, sort_order, students)</p><p>这个程序首先读取学生人数<code>n</code>和排序方式<code>sort_order</code>，然后读取每个学生的名字和成绩，存储在一个列表<code>students</code>中，每个学生的信息是一个元组，包含名字和成绩。之后，调用<code>sort_students</code>函数对学生进行排序并输出。</p><p>在<code>sort_students</code>函数中，使用列表的<code>sort</code>方法对学生信息进行排序，<code>key=lambda x: x[1]</code>指定以成绩作为排序的依据，<code>reverse=(sort_order == 0)</code>根据用户选择的排序方式确定排序方向。</p><p>这样，程序就能根据用户的输入，输出按照指定方式排序后的学生信息了。</p><p>while True: try: count = int(input()) isAsc = int(input()) == 1 pairs = [] for _ in range(count): # 使用for循环正确读取指定行数的输入 name, score = input().split() # 分别读取名字和成绩 pairs.append([name, int(score)]) # 确保成绩是整数形式</p><h1 id="使用sorted函数和reverse参数来根据成绩升序或降序排序" tabindex="-1">使用sorted函数和reverse参数来根据成绩升序或降序排序 <a class="header-anchor" href="#使用sorted函数和reverse参数来根据成绩升序或降序排序" aria-label="Permalink to &quot;使用sorted函数和reverse参数来根据成绩升序或降序排序&quot;">​</a></h1><p>newlist = sorted(pairs, key=lambda x: x[1], reverse=not isAsc) for i in newlist: print(f&quot;{i[0]} {i[1]}&quot;) except EOFError: break</p></div>',1)])])}const m=t(s,[["render",n]]);export{h as __pageData,m as default};
